package gate

import (
	"encoding/json"
	"fmt"
	"github.com/urbanlogiq/ulsdk"
	"testing"
	"time"
)

var _ = fmt.Sprintf
var _ = json.Marshal

func TestBootstrap(t *testing.T) {
	ctx := ulsdk.NewTestContextFromEnv()
	if ctx == nil {
		t.Skip("credentials not set, skipping API test")
	}


	success := false
	for i := 0; i < 5; i++ {
		expected := &BootstrapPayload{}
		expectedBytes, err := json.Marshal(expected)
		if err != nil {
			t.Fatalf("failed to marshal expected: %v", err)
		}
		ctx.SetResponse(expectedBytes)
		result, err := Bootstrap(
			ctx,
		)
		if err != nil {
			time.Sleep(time.Duration(i+1) * time.Second)
			continue
		}
		_ = result
		success = true
		break
	}
	if !success {
		t.Fatal("test was unable to complete with retries")
	}
}
